-- >>> migration_v37.sql
-- =============================================================
--  KULMI migration v37 — anti-ghosting "48h ice-breaker". Idempotent.
--  When a match opens, BOTH people must send a first message within 48h
--  or the match quietly closes and frees both. Once both have spoken the
--  window is lifted for good (ice_deadline -> null).
-- =============================================================

alter table public.chats add column if not exists ice_deadline timestamptz;
alter table public.chats add column if not exists status text not null default 'active';

-- New chats get a 48h window from creation. Backfill existing chats:
--  * if both people already messaged  -> no window (null), it's a live match
--  * otherwise                        -> a fresh 48h grace from now, so no
--    existing conversation is closed retroactively.
update public.chats c
set ice_deadline = case
    when (select count(distinct m.sender_id) from public.messages m where m.chat_id = c.id) >= 2
      then null
    else now() + interval '48 hours'
  end
where c.ice_deadline is null and c.status = 'active';

-- Give the column a default so future inserts (via the accept trigger) get a
-- window automatically without touching that trigger.
alter table public.chats alter column ice_deadline set default (now() + interval '48 hours');

-- -------------------------------------------------------------
-- On every message: block posting into a closed match, and once the OTHER
-- side has already spoken, lift the ice window permanently.
-- -------------------------------------------------------------
create or replace function public.chat_ice_progress()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from public.chats c where c.id = new.chat_id and c.status = 'expired') then
    raise exception 'This match has closed because it went quiet. Please connect with someone new.';
  end if;
  -- If there is already a message from the other person, both sides have now
  -- spoken with this insert — the match is alive, remove the deadline.
  if exists (
    select 1 from public.messages m
    where m.chat_id = new.chat_id and m.sender_id <> new.sender_id
  ) then
    update public.chats set ice_deadline = null
    where id = new.chat_id and ice_deadline is not null;
  end if;
  return new;
end $$;

drop trigger if exists trg_chat_ice_progress on public.messages;
create trigger trg_chat_ice_progress before insert on public.messages
  for each row execute function public.chat_ice_progress();

-- -------------------------------------------------------------
-- Sweep stale (ghosted) matches. Any authenticated member loading their
-- inbox calls this best-effort, so no cron is needed. A match expires only
-- if its window has passed and both sides have not yet spoken.
-- -------------------------------------------------------------
create or replace function public.expire_stale_chats()
returns void language sql security definer set search_path = public as $$
  update public.chats
  set status = 'expired'
  where status = 'active'
    and ice_deadline is not null
    and ice_deadline < now();
$$;
grant execute on function public.expire_stale_chats() to authenticated;

notify pgrst, 'reload schema';


-- >>> migration_v38.sql
-- =============================================================
--  KULMI migration v38 — "Refer someone" (word-of-mouth growth). Idempotent.
--  Members privately nominate a serious person they know; Kulmi sends a warm
--  invite. The referrer stays anonymous unless they choose to be named.
-- =============================================================

create table if not exists public.referrals (
  id           uuid primary key default uuid_generate_v4(),
  referrer_id  uuid references public.profiles(id) on delete set null,
  name         text not null,
  email        text not null,
  reveal_name  boolean not null default false,
  note         text,
  status       text not null default 'sent',   -- sent | joined
  joined_at    timestamptz,
  created_at   timestamptz not null default now()
);

alter table public.referrals enable row level security;

-- A member can create referrals only as themselves, and read only their own.
drop policy if exists "Create own referrals" on public.referrals;
create policy "Create own referrals" on public.referrals for insert to authenticated
  with check (referrer_id = auth.uid());

drop policy if exists "View own referrals" on public.referrals;
create policy "View own referrals" on public.referrals for select to authenticated
  using (referrer_id = auth.uid() or public.is_admin());

-- Spam guard: cap referrals per member (10/day) and stop duplicate emails.
create or replace function public.throttle_referrals()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (select count(*) from public.referrals
      where referrer_id = new.referrer_id and created_at > now() - interval '24 hours') >= 10 then
    raise exception 'You have sent several invitations today — please try again tomorrow.';
  end if;
  if exists (select 1 from public.referrals
      where referrer_id = new.referrer_id and lower(email) = lower(new.email)) then
    raise exception 'You have already invited this person.';
  end if;
  return new;
end $$;

drop trigger if exists trg_throttle_referrals on public.referrals;
create trigger trg_throttle_referrals before insert on public.referrals
  for each row execute function public.throttle_referrals();

notify pgrst, 'reload schema';


-- >>> migration_v39.sql
-- =============================================================
--  KULMI migration v39 — keep compatibility questions in sync. Idempotent.
--  A session snapshots the initiator's (sender's) questions when the invite is
--  accepted. If the sender later edits/reorders their questions BEFORE anyone
--  has answered, the session should reflect that. Clients can't read another
--  member's compat_questions (RLS), so this SECURITY DEFINER function does it.
-- =============================================================

create or replace function public.sync_session_questions(sess uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  snd uuid;
  qs text[];
  answered int;
begin
  -- Only a participant may trigger a sync, and only for their own session.
  select i.sender_id into snd
  from public.sessions s
  join public.invitations i on i.id = s.invitation_id
  where s.id = sess and (s.user1_id = auth.uid() or s.user2_id = auth.uid());
  if snd is null then return; end if;

  -- Never change the question set once answering has begun (keeps answer
  -- indices aligned for both people).
  select count(*) into answered from public.session_answers where session_id = sess;
  if answered > 0 then return; end if;

  select compat_questions into qs from public.profiles where id = snd;
  if qs is not null and array_length(qs, 1) >= 1 then
    update public.sessions set questions = qs
    where id = sess and questions is distinct from qs;
  end if;
end $$;

grant execute on function public.sync_session_questions(uuid) to authenticated;

notify pgrst, 'reload schema';


-- >>> migration_v40.sql
-- =============================================================
--  KULMI migration v40 — working read receipts. Idempotent.
--  Adds messages.read_at and a definer function to mark a chat read. The
--  reader's own "read_receipts" preference is respected: if they turned it off,
--  their reads are never recorded, so the sender never sees "Read".
-- =============================================================

alter table public.messages add column if not exists read_at timestamptz;

create or replace function public.mark_chat_read(c uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  -- Caller must be a participant in the chat.
  if not exists (
    select 1 from public.chats
    where id = c and (user1_id = auth.uid() or user2_id = auth.uid())
  ) then
    return;
  end if;

  -- Respect the reader's privacy toggle: only broadcast reads if it's on.
  if (select coalesce(read_receipts, true) from public.profiles where id = auth.uid()) then
    update public.messages
    set read_at = now()
    where chat_id = c and sender_id <> auth.uid() and read_at is null;
  end if;
end $$;

grant execute on function public.mark_chat_read(uuid) to authenticated;

notify pgrst, 'reload schema';


-- >>> migration_v41.sql
-- =============================================================
--  KULMI migration v41 — push edited compat questions to pending sessions.
--  Idempotent. Runs as the SENDER at save-time (most reliable): any session
--  they initiated (via their invitation) that hasn't been answered yet gets
--  their latest question set immediately.
-- =============================================================

create or replace function public.push_my_compat_questions()
returns void language plpgsql security definer set search_path = public as $$
declare
  qs text[];
begin
  select compat_questions into qs from public.profiles where id = auth.uid();
  if qs is null or array_length(qs, 1) is null then
    return; -- nothing custom to push (defaults stay in place)
  end if;

  update public.sessions s
  set questions = qs
  from public.invitations i
  where i.id = s.invitation_id
    and i.sender_id = auth.uid()
    and not exists (select 1 from public.session_answers a where a.session_id = s.id);
end $$;

